insert into public.notification_templates (usage, message, link) values
  ('signup', '<p>Hi [name],</p><p>Welcome to YALI! Please update your profile by clicking the link below.</p><p>Best,<br/>YALI Team</p>', 'signup'),
  ('update', '<p>Hi [name],</p><p>Please update your profile to reflect any changes in your education, career, or contact information by clicking the link below.</p><p>Best,<br/>YALI Team</p>', 'update'),
  ('updated', '<p>Hi [name],</p><p>Your profile has been successfully updated. You will receive another notification in the next 3 months.</p><p>Best,<br/>YALI Team</p>', 'updated')
